import { marked } from 'marked';
import { useMemo, useRef, useState } from 'react';
import { DEV_STATS, devStatList } from '../lib/devStats';
import { buildCliPrompt } from '../prompts/cliPrompt';
import { buildSpecPrompt } from '../prompts/specPrompt';
import { CopyButton } from './CopyButton';
import { TabPanel, Tabs } from './Tabs';

/** The prompt as HTML. The markdown is generated by the app from its own constants, never from user input. */
export function renderSpec(markdown: string): string {
  return marked.parse(markdown, { async: false, gfm: true }) as string;
}

/** How long a download link's blob URL stays valid after the click. Some browsers start the download asynchronously. */
export const REVOKE_DELAY_MS = 10_000;

/** Offer `text` as a file download. The object URL is revoked later, not synchronously, so the download is never cancelled. */
export function downloadText(text: string, filename: string, type = 'text/markdown'): void {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), REVOKE_DELAY_MS);
}

type PromptId = 'app' | 'cli';

/** The two prompts, in the order they are built: the app, then the command line on its shared core. */
const PROMPTS: readonly { id: PromptId; label: string; build: () => string; file: string; about: string }[] = [
  {
    id: 'app',
    label: '1. The web app',
    build: buildSpecPrompt,
    file: 'elegant-passwords-spec.md',
    about: 'Every option and feature of this app and how each works, with the shared core every algorithm lives in.',
  },
  {
    id: 'cli',
    label: '2. The command line',
    build: buildCliPrompt,
    file: 'tep-cli-spec.md',
    about: 'tep, the command line: built after the web app, on its shared core, which it reuses by name instead of redefining.',
  },
];

export function FunPage() {
  const [tab, setTab] = useState<PromptId>('app');
  return (
    <section className="fun">
      <div className="fun-head">
        <div>
          <h2>Rebuild this app from two prompts</h2>
          <p className="hint">
            A full spec of every option and feature and how each works, generated from the app’s own settings, so it
            always matches. Paste the first into an AI coding assistant to build Elegant Passwords from scratch, then the
            second to add tep, its command line. Copy or download the markdown of each.
          </p>
        </div>
      </div>
      <DevStatsPanel />
      <Tabs tabs={PROMPTS.map((p) => ({ id: p.id, label: p.label }))} value={tab} onChange={setTab} label="Prompts" idPrefix="prompt" />
      {PROMPTS.map((p) => (
        <TabPanel key={p.id} idPrefix="prompt" id={p.id} active={tab === p.id} className="fun-panel">
          <PromptPanel build={p.build} file={p.file} about={p.about} />
        </TabPanel>
      ))}
    </section>
  );
}

function PromptPanel({ build, file, about }: { build: () => string; file: string; about: string }) {
  const prompt = useMemo(() => build(), [build]);
  const html = useMemo(() => renderSpec(prompt), [prompt]);
  const pre = useRef<HTMLDivElement>(null);
  return (
    <>
      <div className="fun-head">
        <p className="hint">{about}</p>
        <div className="actions">
          <span className="bits-label">{prompt.split(/\s+/).length.toLocaleString('en')} words</span>
          <CopyButton text={prompt} fallback={pre} label="Copy prompt" />
          <button type="button" onClick={() => downloadText(prompt, file)}>
            Download .md
          </button>
        </div>
      </div>
      <div className="prompt prose" ref={pre} dangerouslySetInnerHTML={{ __html: html }} />
    </>
  );
}

/** How the app itself was built: tokens, models, code, time and commits, as of the last `pnpm stats`. */
function DevStatsPanel() {
  const asOf = new Date(DEV_STATS.asOf).toLocaleDateString('en', { year: 'numeric', month: 'short', day: 'numeric' });
  return (
    <section className="dev-stats" aria-labelledby="dev-stats-heading">
      <h3 id="dev-stats-heading">How this app was made</h3>
      <dl>
        {devStatList().map((s) => (
          <div key={s.label}>
            <dt>{s.label}</dt>
            <dd>{s.value}</dd>
            <dd className="hint">{s.detail}</dd>
          </div>
        ))}
      </dl>
      <p className="hint">As of {asOf}, from this project’s AI coding transcripts and git history.</p>
    </section>
  );
}
